-- ── _prisma_migrations bookkeeping (real sha256 checksums — Prisma's own
--    scheme — so `migrate deploy` no-ops instead of re-applying) ─────────
CREATE TABLE IF NOT EXISTS "_prisma_migrations" (
  "id" VARCHAR(36) NOT NULL,
  "checksum" VARCHAR(64) NOT NULL,
  "finished_at" TIMESTAMPTZ,
  "migration_name" VARCHAR(255) NOT NULL,
  "logs" TEXT,
  "rolled_back_at" TIMESTAMPTZ,
  "started_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
  "applied_steps_count" INTEGER NOT NULL DEFAULT 0
);
DO $$ BEGIN
  ALTER TABLE "_prisma_migrations" ADD PRIMARY KEY ("id");
EXCEPTION
  WHEN duplicate_object THEN NULL;         -- constraint already exists
  WHEN invalid_table_definition THEN NULL; -- a PK already exists (re-paste)
END $$;
